import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t,o as s,c as a,a3 as i}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"Libre NFC","description":"","frontmatter":{"source_hash":"9c60a43392","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/install/libreNFC.md","filePath":"fr/install/libreNFC.md"}'),n={name:"fr/install/libreNFC.md"};function o(l,e,c,u,p,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<p>Aujourd&#39;hui, presque tous les téléphones prennent en charge le scan NFC. Si c&#39;est le cas du vôtre, vous pouvez scanner votre capteur Libre 1, US 14 jours, Libre 2/2+ (EU) et Libre Pro avec xDrip en plus de l&#39;application LibreLink du fabricant. Attention : le scan NFC de xDrip <strong>ne peut pas</strong> démarrer un capteur, seul LibreLink (ou le lecteur) peut le faire.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   LibreAlarm</p></div><h2 id="supported-data-sources" tabindex="-1">Sources de données prises en charge <a class="header-anchor" href="#supported-data-sources" aria-label="Permalink to &quot;Sources de données prises en charge {#supported-data-sources}&quot;">​</a></h2><p>Pour accéder au menu NFC, vous devez sélectionner l&#39;une des sources de données Libre.</p><p>Si vous n&#39;utilisez xDrip que pour scanner le capteur, choisissez LibreAlarm.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Si vous activez la prise en charge du scan NFC dans xDrip, désactivez toute autre application susceptible de lire les appareils NFC afin d&#39;éviter les conflits. C&#39;est particulièrement vrai pour l&#39;application Libre du fabricant.</p></div><h4 id="configure-nfc" tabindex="-1">Configurer le NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configurer le NFC {#configure-nfc}&quot;">​</a></h4><p>Configurez le NFC exactement <a href="./../use/NFC.html">comme ceci</a>.</p><h2 id="supported-sensors" tabindex="-1">Capteurs pris en charge <a class="header-anchor" href="#supported-sensors" aria-label="Permalink to &quot;Capteurs pris en charge {#supported-sensors}&quot;">​</a></h2><p>Seuls les Libre 1 et Pro sont pris en charge nativement par xDrip pour les lectures NFC. Pour scanner un Libre 14 jours US ou un Libre 2 Europe, vous devez installer un <a href="./../use/OOP.html">algorithme hors processus (OOP)</a> sur le téléphone.</p><table tabindex="0"><thead><tr><th style="text-align:center;">- Libre 1 / Pro -</th><th style="text-align:center;">- 14 jours US -</th><th style="text-align:center;">- Libre 2/2+ EU -</th></tr></thead><tbody><tr><td style="text-align:center;"><code>Oui</code></td><td style="text-align:center;"><code>OOP2</code></td><td style="text-align:center;"><code>OOP2</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Intervalle minimal entre deux scans</p><p>Attendez au moins 60 secondes entre deux scans NFC.</p></div><br><p>Passez ensuite à <a href="./../use/startsensor.html#libre">Démarrer le capteur</a>, en sachant que vous devrez scanner le capteur pour obtenir les premières valeurs.</p><br><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 6/12/2024</em></a></p>',17)])])}const f=t(n,[["render",o]]);export{b as __pageData,f as default};
